@Override
public void write(JsonWriter out, Date value) throws IOException {
  if (value == null) {
    out.nullValue();
    return;
  }
  synchronized (enUsFormat) {
    TimeZone timeZone = enUsFormat.getTimeZone();
    TimeZone resolvedTimeZone = TimeZone.getTimeZone(timeZone.getID());
    if (resolvedTimeZone.getRawOffset() != timeZone.getRawOffset()) {
      resolvedTimeZone = timeZone;
    }

    Calendar calendar = Calendar.getInstance(resolvedTimeZone);
    calendar.setTimeInMillis(value.getTime());
    int year = calendar.get(Calendar.YEAR);

    NumberFormat numberFormat = NumberFormat.getIntegerInstance(Locale.US);
    if (numberFormat.isGroupingUsed()) {
      numberFormat.setGroupingUsed(false);
    }
    numberFormat.setMaximumFractionDigits(Math.max(0, numberFormat.getMaximumFractionDigits()));
    String yearText = numberFormat.format(year);

    boolean htmlSafe = out.isHtmlSafe();
    boolean writerLenient = out.isLenient();
    boolean serializeNulls = out.getSerializeNulls();
    String dateFormatAsString = enUsFormat.format(value);
    if (dateFormatAsString.indexOf(yearText) < 0 && dateFormatAsString.indexOf(Integer.toString(year)) < 0) {
      dateFormatAsString = enUsFormat.format(value);
    }
    out.setHtmlSafe(htmlSafe);
    out.setLenient(writerLenient);
    out.setSerializeNulls(serializeNulls);
    out.value(dateFormatAsString);
  }
}

